"use client"

import { useEffect, useId, useRef, useState } from "react"
import { cn } from "cn"

/** Only already-projected, local specimen routes are accepted; never arbitrary URLs or code. */
export function specimenSource(src: string, viewport?: Viewport): string {
  if (/[\\\s\u0000-\u001f\u007f]/.test(src) || !src.startsWith("/") || src.startsWith("//")) {
    throw new Error("Expected a local specimen route")
  }
  const url = new URL(src, "https://example.com")
  if (url.pathname !== "/__specimen" && !url.pathname.startsWith("/preview/")) {
    throw new Error("Expected a projected specimen route")
  }
  if (viewport !== undefined) {
    const widths = url.searchParams.getAll("width")
    // Producer's existing routes default to 1280 when width is absent.
    if (![375, 768, 1280].includes(viewport) || widths.length > 1 || (widths.length ? widths[0] !== String(viewport) : viewport !== 1280)) {
      throw new Error("Specimen viewport does not match its projected source")
    }
  }
  return src
}

type Viewport = 375 | 768 | 1280

/** Bounded content-size data fit. This is local adaptation code, not upstream BlockViewer code. */
export function specimenContentHeight(data: unknown, viewport: Viewport, width: number, ceiling: number): number | undefined {
  if (!data || typeof data !== "object") return undefined
  const size = data as Record<string, unknown>
  if (size.type !== "clossys:specimen-size" || size.width !== viewport || typeof size.height !== "number" || !Number.isFinite(size.height) || size.height <= 0) return undefined
  if (!Number.isFinite(width) || width <= 0 || !Number.isFinite(ceiling) || ceiling <= 0) return undefined
  return Math.max(1, Math.min(ceiling, Math.ceil(size.height * Math.min(1, width / viewport))))
}

/** Bind one element/id/window/source for this lifecycle. A changed source gets a new keyed iframe. */
export function observeSpecimenSize(frame: HTMLIFrameElement, viewport: Viewport, ceiling: number, onHeight: (height: number) => void): () => void {
  const document = frame.ownerDocument
  const host = document.defaultView
  if (!host || !frame.id) return () => {}
  const id = frame.id
  const src = frame.getAttribute("src")
  const expected = new URL(specimenSource(src ?? "", viewport), host.location.href)
  const target = frame.contentWindow
  let active = true
  let loaded = false
  let lastSize: unknown
  const current = () => {
    if (!active || !frame.isConnected || frame.id !== id || document.getElementById(id) !== frame || frame.getAttribute("src") !== src || !target || frame.contentWindow !== target) return false
    try { return expected.origin === host.location.origin && target.location.href === expected.href } catch { return false }
  }
  const fit = () => {
    if (!loaded || !current()) return
    const height = specimenContentHeight(lastSize, viewport, frame.clientWidth, ceiling)
    if (height !== undefined) onHeight(height)
  }
  const load = () => {
    lastSize = undefined
    loaded = current()
    if (loaded) onHeight(ceiling)
  }
  const message = (event: MessageEvent) => {
    if (!loaded || !current() || event.origin !== expected.origin || event.source !== target) return
    if (specimenContentHeight(event.data, viewport, frame.clientWidth, ceiling) === undefined) return
    lastSize = event.data
    fit()
  }
  frame.addEventListener("load", load)
  host.addEventListener("message", message)
  const observer = typeof ResizeObserver === "undefined" ? undefined : new ResizeObserver(fit)
  observer?.observe(frame)
  // A cached frame may finish before React installs the effect listener.
  try { if (current() && target?.document.readyState === "complete") load() } catch { /* A navigated frame is rejected by current(). */ }
  return () => {
    active = false
    loaded = false
    lastSize = undefined
    observer?.disconnect()
    frame.removeEventListener("load", load)
    host.removeEventListener("message", message)
  }
}

export interface BlockViewerIframeProps {
  src: string
  title: string
  viewport: Viewport
  iframeKey: string | number
  iframeHeight?: number
  interactive?: boolean
  className?: string
}

/** Draft extraction of the official BlockViewerIframe; see stock-layout.provenance.json. */
export function BlockViewerIframe(props: BlockViewerIframeProps) {
  return <BoundBlockViewerIframe key={JSON.stringify([props.iframeKey, props.src, props.viewport, props.iframeHeight])} {...props} />
}

function BoundBlockViewerIframe({ src, title, viewport, iframeKey, iframeHeight = 930, interactive = false, className }: BlockViewerIframeProps) {
  if (!Number.isFinite(iframeHeight) || iframeHeight <= 0 || iframeHeight > 10000) throw new Error("Invalid specimen height")
  const source = specimenSource(src, viewport)
  const id = useId()
  const ref = useRef<HTMLIFrameElement>(null)
  const [height, setHeight] = useState(iframeHeight)
  useEffect(() => {
    if (!ref.current) return
    return observeSpecimenSize(ref.current, viewport, iframeHeight, setHeight)
  }, [source, viewport, iframeHeight])

  return (
    <iframe
      key={iframeKey}
      src={source}
      height={height}
      loading="lazy"
      className={cn(
        "relative z-20 no-scrollbar w-full bg-background",
        className
      )}
      ref={ref}
      id={id}
      title={title}
      inert={!interactive}
    />
  )
}

import { Badge, Card, CardContent, CardDescription, CardGrid, CardHeader, CardTitle, LinkButton, Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@clossys/designer-ui';

import { BlockViewerIframe } from './BlockViewerIframe';

export type SpecimenTone = 'secondary' | 'outline' | 'destructive';

/** One viewport's specimen URLs; the frame renders the page at `viewport` CSS px and scales it to fit. */
export interface ViewportSpecimen {
  viewport: 375 | 768 | 1280; light: string; dark?: string;
  /** False for a preview in a list (a gallery card): the frame is view-only so the page scrolls past it. */
  interactive?: boolean;
}

/** A structured record kind (Writer voice, claims, names; Director direction): one titled table. */
export interface SpecimenTable {
  id: string;
  label: string;
  columns: readonly string[];
  /** The prose column, given a readable minimum width. */
  prose?: number;
  rows: readonly { key: string; cells: readonly { text: string; href?: string; statusLabel?: string; statusTone?: SpecimenTone }[] }[];
}

/**
 * The `specimen` input of `sections.studio.specimen`, one shape for every agent:
 * `viewports` frames rendered output (Designer items, Publisher pages) at 375/768/1280 in light
 * and, when the source has one, dark; `record` lays out a record's own content as tables or rows.
 */
export type SpecimenInput = { name: string; title: string; description: string } & (
  | { kind: 'viewports'; specimens: readonly ViewportSpecimen[]; empty: string }
  | { kind: 'record'; tables?: readonly SpecimenTable[]; rows?: readonly { key: string; label: string; text: string; href?: string }[]; status?: { label: string; tone: SpecimenTone; description: string }; empty: string }
);

/**
 * Every viewport in one vertical run, widest first, each a headed row of its light and dark frames
 * (no tabs). A single viewport, as a gallery card shows it, is the frame alone at full width.
 * The extracted stock iframe uses the projected viewport and bounded local content-size binding.
 * The surrounding light/dark comparison layout remains pending a verified stock composition.
 */
function Viewports({ name, specimens, empty }: { name: string; specimens: readonly ViewportSpecimen[]; empty: string }) {
  if (!specimens.length) return <CardContent><Badge variant="outline" data-preview-status="empty">{empty}</Badge></CardContent>;
  const rows = [...specimens].sort((a, b) => b.viewport - a.viewport);
  return <CardContent className="flex flex-col gap-4">
    {rows.map(row => <CardContent key={row.viewport} className="flex flex-col gap-2 px-0" data-specimen-viewport={row.viewport}>
      {rows.length > 1 && <CardDescription role="heading" aria-level={3} className="font-medium text-foreground">{row.viewport} px</CardDescription>}
      <CardGrid density={row.dark ? 'specimens' : undefined} className={row.dark ? undefined : 'grid-cols-1'}>
        <BlockViewerIframe iframeKey={`${name}:${row.viewport}:light`} viewport={row.viewport} interactive={row.interactive ?? true} title={`${name} at ${row.viewport} px${row.dark ? ', light' : ''}`} src={row.light} />
        {row.dark && <BlockViewerIframe iframeKey={`${name}:${row.viewport}:dark`} viewport={row.viewport} interactive={row.interactive ?? true} title={`${name} at ${row.viewport} px, dark`} src={row.dark} />}
      </CardGrid>
    </CardContent>)}
  </CardContent>;
}

function RecordTable({ name, table, titled }: { name: string; table: SpecimenTable; titled: boolean }) {
  return <CardContent className="flex flex-col gap-2">
    {titled && <CardDescription role="heading" aria-level={3} className="font-medium text-foreground">{table.label}</CardDescription>}
    <Table aria-label={`${name} ${table.label}`}>
      <TableHeader>
        {table.columns.map((column, index) => <TableHead key={column} isRowHeader={index === 0}>{column}</TableHead>)}
      </TableHeader>
      <TableBody>
        {table.rows.map(row => <TableRow key={row.key} id={row.key}>
          {row.cells.map((cell, index) => <TableCell key={index} className={index === table.prose ? 'min-w-48 whitespace-pre-wrap' : 'whitespace-pre-wrap'}>
            {cell.href ? <LinkButton href={cell.href} variant="link" size="sm" className="h-auto px-0 text-left whitespace-pre-wrap break-words">{cell.text}</LinkButton> : cell.text}
            {cell.statusLabel && <Badge variant={cell.statusTone ?? 'outline'} className="ml-2">{cell.statusLabel}</Badge>}
          </TableCell>)}
        </TableRow>)}
      </TableBody>
    </Table>
  </CardContent>;
}

/** The specimen body without its card: what the leaf produces. A gallery card places it under its own header. */
export function SpecimenContent({ specimen }: { specimen: SpecimenInput }) {
  if (specimen.kind === 'viewports') return <Viewports name={specimen.name} specimens={specimen.specimens} empty={specimen.empty} />;
  if (specimen.tables?.length) return <>{specimen.tables.map(table => <RecordTable key={table.id} name={specimen.name} table={table} titled={specimen.tables!.length > 1} />)}</>;
  if (specimen.rows?.length) return <CardContent>
    <Table aria-label={`${specimen.name} specimen`}>
      <TableHeader>
        <TableHead isRowHeader>Key</TableHead>
        <TableHead>Content</TableHead>
      </TableHeader>
      <TableBody>
        {specimen.rows.map(row => <TableRow key={row.key} id={row.key}>
          <TableCell>{row.label}</TableCell>
          <TableCell className="whitespace-pre-wrap">
            {row.href ? <LinkButton href={row.href} variant="link" size="sm" className="h-auto px-0 text-left whitespace-pre-wrap break-words">{row.text}</LinkButton> : row.text}
          </TableCell>
        </TableRow>)}
      </TableBody>
    </Table>
  </CardContent>;
  if (specimen.status) return <CardContent className="flex flex-col items-start gap-2">
    <Badge variant={specimen.status.tone} data-preview-status="status">{specimen.status.label}</Badge>
    <CardDescription>{specimen.status.description}</CardDescription>
  </CardContent>;
  return <CardContent><Badge variant="outline" data-preview-status="empty">{specimen.empty}</Badge></CardContent>;
}

/** `sections.studio.specimen`: what the leaf produces, framed at every viewport or laid out as its record content. */
export default function SpecimenSection({ specimen }: { specimen: SpecimenInput }) {
  return <Card size="sm" data-studio-section="specimen">
    <CardHeader>
      <CardTitle role="heading" aria-level={2}>{specimen.title}</CardTitle>
      <CardDescription>{specimen.description}</CardDescription>
    </CardHeader>
    <SpecimenContent specimen={specimen} />
  </Card>;
}

